package dev.vadyanik.smartshots.gui;

import dev.vadyanik.smartshots.SmartShots;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.SpriteIconButton;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;

/** Pixel-art GUI sprites (assets/smartshots/textures/gui/sprites, generated by tools/icons.py). */
public final class Icons {
	public static final Identifier CAMERA = SmartShots.id("camera");
	public static final Identifier SETTINGS = SmartShots.id("settings");
	public static final Identifier FOLDER = SmartShots.id("folder");
	public static final Identifier CLOSE = SmartShots.id("close");
	public static final Identifier INFO = SmartShots.id("info");
	public static final Identifier TRASH = SmartShots.id("trash");
	public static final Identifier OPEN = SmartShots.id("open");
	public static final Identifier STAR = SmartShots.id("star");
	public static final Identifier STAR_EMPTY = SmartShots.id("star_empty");
	public static final Identifier NOTE = SmartShots.id("note");
	public static final Identifier ARROW_LEFT = SmartShots.id("arrow_left");
	public static final Identifier ARROW_RIGHT = SmartShots.id("arrow_right");
	public static final Identifier BADGE_TROPHY = SmartShots.id("badge_trophy");
	public static final Identifier BADGE_CLOCK = SmartShots.id("badge_clock");
	public static final Identifier BADGE_PLAYER = SmartShots.id("badge_player");
	public static final Identifier BADGE_STAR = SmartShots.id("badge_star");
	public static final Identifier ALL = SmartShots.id("all");
	public static final Identifier EXPAND_RIGHT = SmartShots.id("expand_right");
	public static final Identifier EXPAND_DOWN = SmartShots.id("expand_down");
	public static final Identifier HERE = SmartShots.id("here");

	private Icons() {
	}

	public static void draw(GuiGraphicsExtractor g, Identifier sprite, int x, int y, int size) {
		g.blitSprite(RenderPipelines.GUI_TEXTURED, sprite, x, y, size, size);
	}

	public static void draw(GuiGraphicsExtractor g, Identifier sprite, int x, int y, int w, int h, int color) {
		g.blitSprite(RenderPipelines.GUI_TEXTURED, sprite, x, y, w, h, color);
	}

	/** Square 20x20 icon button with a tooltip, like the vanilla title screen buttons. */
	public static SpriteIconButton button(Identifier sprite, Component tooltip, Button.OnPress onPress) {
		return SpriteIconButton.builder(tooltip, onPress, true)
			.width(20)
			.sprite(sprite, 15, 15)
			.withTootip()
			.build();
	}
}
